//! `asb`: the agent secret broker's command line, a Rust port of client/asb.
//!
//! While both exist the Python client is the specification: this prints the same text, exits with the same codes and
//! sends the same requests, and tools/run_tests_against_rust_cli.py runs the existing test-suite against this binary.
//! See docs/proposals/rust-cli.md for the order the commands move over in.

mod approval;
mod broker;
mod cmd;
mod cmd_agent_setup;
mod cmd_audit;
mod cmd_enroll;
mod cmd_guidance;
mod cmd_http;
mod cmd_store;
mod cmd_sudo;
mod difflib;
mod exit;
mod pyfmt;
// generated by tools/sync_cli_text.py: formatted by the tool, not rustfmt
#[rustfmt::skip]
mod text_gen;
mod util;

fn main() {
    // Like most command-line tools, stop quietly when whatever reads our output goes away (`asb list | head`).
    unsafe {
        libc::signal(libc::SIGPIPE, libc::SIG_DFL);
    }
    let args: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    std::process::exit(cmd::run(&args));
}
